 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, smoothstep, sin, fract, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, DoubleSide } = THREE;

  const root = new Group();

  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const colors = {
    ink: new THREE.Color(specColors.ink ?? '#16161d'),
    paper: new THREE.Color(specColors.paper ?? '#e8ecf2'),
    accent: new THREE.Color(specColors.accent ?? '#ff2a38'),
    surface: new THREE.Color(specColors.surface ?? '#0b0b10'),
  };

  // Backdrop: engineered gradient surface + subtle grain
  const backdropGeo = new PlaneGeometry(7.2, 6.0);
  const uvNode = uv();
  const gradientT = smoothstep(0.2, 0.9, uvNode.y);
  const gradient = mix(color(colors.surface), color(colors.ink), gradientT);
  const grainInput = uvNode.mul(420.0);
  const grain = fract(sin(grainInput.dot(vec2(12.9898, 78.233))).mul(43758.5453));
  const grainTinted = mix(gradient, color(colors.paper), grain.mul(0.04));
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: grainTinted });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // Textured card plane
  const cardAspect = 512 / 320;
  const cardWidth = 2.0;
  const cardHeight = cardWidth / cardAspect;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  cardMat.opacity = 0;
  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0.05;
  root.add(card);

  let texResource = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texResource = tex;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  const timelines = [];

  // Apply any cinematic primitives listed in config
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](root, p.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) {
        const existing = root.userData.cleanup;
        root.userData.cleanup = () => {
          if (typeof existing === 'function') existing();
          result.cleanup();
        };
      }
    }
  }

  // Subtle entrance: static composition, no idle or interaction motion
  const entranceTl = gsap.timeline({ delay: 0.1 });
  entranceTl
    .from(card.position, { y: -0.35, duration: 0.75, ease: 'power3.out' }, 0)
    .from(card.scale, { x: 0.92, y: 0.92, duration: 0.75, ease: 'power3.out' }, 0)
    .from(cardMat, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0);
  timelines.push(entranceTl);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    if (texResource) texResource.dispose();
  };

  return root;
}
